+import Yoga from 'yoga-layout';
+import {type DOMElement} from './dom.js';
+
+type Track = {minimum: number; fraction: number; auto: boolean};
+type Placement = {node: DOMElement; column: number; columnEnd: number; row: number; rowEnd: number};
+
+const tokenPattern = /minmax\\([^)]*\\)|[^\\s]+/g;
+
+const parseTrack = (value: string): Track => {
+	if (value === 'auto') return {minimum: 0, fraction: 0, auto: true};
+	const fraction = /^(\\d*\\.?\\d+)fr$/.exec(value);
+	if (fraction) return {minimum: 0, fraction: Number(fraction[1]), auto: false};
+	const fixed = Number(value);
+	if (Number.isFinite(fixed) && fixed >= 0) return {minimum: fixed, fraction: 0, auto: false};
+	const minmax = /^minmax\\(\\s*(\\d*\\.?\\d+)\\s*,\\s*(?:(\\d*\\.?\\d+)|(\\d*\\.?\\d+)fr)\\s*\\)$/.exec(value);
+	if (minmax) return {minimum: Number(minmax[1]), fraction: Number(minmax[3] ?? 0), auto: false};
+	throw new Error(`Invalid grid track size: ${value}`);
+};
+
+const parseTracks = (template?: string): Track[] =>
+	template ? (template.match(tokenPattern) ?? []).map(parseTrack) : [];
+
+const parsePlacement = (value: number | string | undefined): [number?, number?] => {
+	if (typeof value === 'number') return [value, value + 1];
+	if (!value) return [];
+	const parts = value.split('/').map(part => Number(part.trim()));
+	if (parts.length === 1 && Number.isInteger(parts[0]) && parts[0]! > 0) return [parts[0], parts[0]! + 1];
+	if (parts.length === 2 && parts.every(part => Number.isInteger(part) && part > 0) && parts[0]! < parts[1]!) return [parts[0], parts[1]];
+	throw new Error(`Invalid grid placement: ${value}`);
+};
+
+const overlaps = (a: Placement, column: number, columnEnd: number, row: number, rowEnd: number) =>
+	a.column < columnEnd && column < a.columnEnd && a.row < rowEnd && row < a.rowEnd;
+
+const getGap = (node: DOMElement, axis: 'column' | 'row') =>
+	axis === 'column'
+		? (node.style.columnGap ?? node.style.gap ?? 0)
+		: (node.style.rowGap ?? node.style.gap ?? 0);
+
+const sizeTracks = (tracks: Track[], available: number, gap: number, measurements: number[]): number[] => {
+	const sizes = tracks.map((track, index) => track.auto ? Math.max(track.minimum, measurements[index] ?? 0) : track.minimum);
+	const free = Math.max(0, available - sizes.reduce((sum, size) => sum + size, 0) - Math.max(0, tracks.length - 1) * gap);
+	const fractions = tracks.reduce((sum, track) => sum + track.fraction, 0);
+	if (fractions > 0) {
+		for (const [index, track] of tracks.entries()) sizes[index]! += free * track.fraction / fractions;
+	}
+	return sizes;
+};
+
+const layoutGrid = (container: DOMElement): void => {
+	const node = container.yogaNode;
+	if (!node || container.style.display !== 'grid') return;
+	const children = container.childNodes.filter((child): child is DOMElement => child.nodeName !== '#text' && Boolean(child.yogaNode) && child.yogaNode!.getDisplay() !== Yoga.DISPLAY_NONE);
+	let columns = parseTracks(container.style.gridTemplateColumns);
+	const specifiedColumns = children.map(child => parsePlacement(child.style.gridColumn)[1] ?? 1);
+	if (columns.length === 0) columns = Array.from({length: Math.max(1, ...specifiedColumns)}, () => ({minimum: 0, fraction: 1, auto: false}));
+	const placements: Placement[] = [];
+	let cursorColumn = 1;
+	let cursorRow = 1;
+	for (const child of children) {
+		let [column, columnEnd] = parsePlacement(child.style.gridColumn);
+		let [row, rowEnd] = parsePlacement(child.style.gridRow);
+		const columnSpan = (columnEnd ?? (column ? column + 1 : undefined))! - (column ?? 0) || 1;
+		const rowSpan = (rowEnd ?? (row ? row + 1 : undefined))! - (row ?? 0) || 1;
+		if (!column) {
+			column = cursorColumn;
+			while (column + columnSpan - 1 > columns.length || placements.some(item => overlaps(item, column!, column! + columnSpan, row ?? cursorRow, (row ?? cursorRow) + rowSpan))) {
+				column++;
+				if (column > columns.length) { column = 1; cursorRow++; }
+			}
+			columnEnd = column + columnSpan;
+		}
+		if (!row) {
+			row = cursorRow;
+			while (placements.some(item => overlaps(item, column!, columnEnd!, row!, row! + rowSpan))) row++;
+			rowEnd = row + rowSpan;
+		}
+		placements.push({node: child, column, columnEnd: columnEnd!, row, rowEnd: rowEnd!});
+		cursorColumn = columnEnd!;
+		if (cursorColumn > columns.length) { cursorColumn = 1; cursorRow = row + 1; }
+	}
+
+	let rows = parseTracks(container.style.gridTemplateRows);
+	const rowCount = Math.max(0, ...placements.map(item => item.rowEnd - 1));
+	while (rows.length < rowCount) rows.push({minimum: 0, fraction: 0, auto: true});
+	const columnMeasurements = columns.map(() => 0);
+	const rowMeasurements = rows.map(() => 0);
+	for (const item of placements) {
+		if (item.columnEnd - item.column === 1) columnMeasurements[item.column - 1] = Math.max(columnMeasurements[item.column - 1]!, item.node.yogaNode!.getComputedWidth());
+		if (item.rowEnd - item.row === 1) rowMeasurements[item.row - 1] = Math.max(rowMeasurements[item.row - 1]!, item.node.yogaNode!.getComputedHeight());
+	}
+	const columnGap = getGap(container, 'column');
+	const rowGap = getGap(container, 'row');
+	const contentWidth = Math.max(0, node.getComputedWidth() - node.getComputedPadding(Yoga.EDGE_LEFT) - node.getComputedPadding(Yoga.EDGE_RIGHT) - node.getComputedBorder(Yoga.EDGE_LEFT) - node.getComputedBorder(Yoga.EDGE_RIGHT));
+	const contentHeight = Math.max(0, node.getComputedHeight() - node.getComputedPadding(Yoga.EDGE_TOP) - node.getComputedPadding(Yoga.EDGE_BOTTOM) - node.getComputedBorder(Yoga.EDGE_TOP) - node.getComputedBorder(Yoga.EDGE_BOTTOM));
+	const columnSizes = sizeTracks(columns, contentWidth, columnGap, columnMeasurements);
+	const rowSizes = sizeTracks(rows, contentHeight, rowGap, rowMeasurements);
+	if (!('height' in container.style)) node.setHeight(rowSizes.reduce((sum, size) => sum + size, 0) + Math.max(0, rows.length - 1) * rowGap + node.getComputedPadding(Yoga.EDGE_TOP) + node.getComputedPadding(Yoga.EDGE_BOTTOM) + node.getComputedBorder(Yoga.EDGE_TOP) + node.getComputedBorder(Yoga.EDGE_BOTTOM));
+	for (const item of placements) {
+		const left = columnSizes.slice(0, item.column - 1).reduce((sum, size) => sum + size, 0) + (item.column - 1) * columnGap;
+		const top = rowSizes.slice(0, item.row - 1).reduce((sum, size) => sum + size, 0) + (item.row - 1) * rowGap;
+		const width = columnSizes.slice(item.column - 1, item.columnEnd - 1).reduce((sum, size) => sum + size, 0) + (item.columnEnd - item.column - 1) * columnGap;
+		const height = rowSizes.slice(item.row - 1, item.rowEnd - 1).reduce((sum, size) => sum + size, 0) + (item.rowEnd - item.row - 1) * rowGap;
+		item.node.yogaNode!.setPositionType(Yoga.POSITION_TYPE_ABSOLUTE);
+		item.node.yogaNode!.setPosition(Yoga.EDGE_LEFT, left);
+		item.node.yogaNode!.setPosition(Yoga.EDGE_TOP, top);
+		item.node.yogaNode!.setWidth(width);
+		item.node.yogaNode!.setHeight(height);
+	}
+};
+
+export const applyGridLayout = (node: DOMElement): void => {
+	for (const child of node.childNodes) if (child.nodeName !== '#text') applyGridLayout(child);
+	layoutGrid(node);
+};
